      'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,
      'config',p.proconfig,'security_definer',p.prosecdef))
      from (values ('manifest','sl_private.manifest()'),('catalog','sl_private.quiz_catalog()'),('reader','public.sl_get_progress()'),('writer','public.sl_apply_event(uuid,bigint,jsonb)')) v(name,sig) left join pg_proc p on p.oid=to_regprocedure(v.sig)) is distinct from $post_functions${"reader":{"md5":"da315179151a87bf3ef65d29853a5cb1","owner":"postgres","acl":["postgres=X/postgres","authenticated=X/postgres"],"config":["search_path=\"\""],"security_definer":true,"definition_md5":"84cc70c3d8d687433d0166f59ece1406"},"writer":{"md5":"716c0abbb2ba64ded03208d48e9ddc95","owner":"postgres","acl":["postgres=X/postgres","authenticated=X/postgres"],"config":["search_path=\"\""],"security_definer":true,"definition_md5":"45ded0a707c7afb3a0f5ebc8b22a730d"},"catalog":{"md5":"0025ed48bee7255bd7bac515d94324b9","owner":"postgres","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"security_definer":false,"definition_md5":"0a1508fc57275c321b7163c82be5bc2e"},"manifest":{"md5":"497a7d88ae6509e51dd7cd26b22e5e80","owner":"postgres","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"security_definer":false,"definition_md5":"df19b0162616dfe0ce506bff55816dc6"}}$post_functions$::jsonb then
