      'owner',pg_get_userbyid(p.proowner),'acl',p.proacl,
      'config',p.proconfig,'security_definer',p.prosecdef)),'{}'::jsonb)
      from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='sl_private' and p.proname ~ '^(manifest|quiz_catalog)_before_0(18|19|20|21|22)$') is distinct from $old_archives${"manifest_before_021":{"md5":"403ce93926cb464c309858138ca9596b","owner":"postgres","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"security_definer":false,"definition_md5":"d58168eeffda3eb0aa9602d182e4b155"},"manifest_before_022":{"md5":"c414177b861e8e9871be4ceb811ca38a","owner":"postgres","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"security_definer":false,"definition_md5":"c47c935ef43216aade036d663c185ba9"},"quiz_catalog_before_020":{"md5":"2c44acc6ab5f99bca18a46495269a4f4","owner":"postgres","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"security_definer":false,"definition_md5":"8900adc5d2d4ecf17a6e706c0416d4ac"},"quiz_catalog_before_021":{"md5":"f5df12b82749eda17a450f1622701a7c","owner":"postgres","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"security_definer":false,"definition_md5":"28a8a849d9bded4c0c577b777b1b27dd"},"quiz_catalog_before_022":{"md5":"104dfa947eef31cc6d551f12e78acdef","owner":"postgres","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"security_definer":false,"definition_md5":"c6b02246f57af265ce74cc623e69bdd0"}}$old_archives$::jsonb then
